func (mmWithf *mLoggerAliasMockWithf) invocationsDone() bool {
	if len(mmWithf.expectations) == 0 && mmWithf.defaultExpectation == nil && mmWithf.mock.funcWithf == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmWithf.mock.afterWithfCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmWithf.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// Withf implements loggerAlias
func (mmWithf *LoggerAliasMock) Withf(key logger.Field, value any) (l1 logger.Logger) {
	mm_atomic.AddUint64(&mmWithf.beforeWithfCounter, 1)
	defer mm_atomic.AddUint64(&mmWithf.afterWithfCounter, 1)

	mmWithf.t.Helper()

	if mmWithf.inspectFuncWithf != nil {
		mmWithf.inspectFuncWithf(key, value)
	}

	mm_params := LoggerAliasMockWithfParams{key, value}

	// Record call args
	mmWithf.WithfMock.mutex.Lock()
	mmWithf.WithfMock.callArgs = append(mmWithf.WithfMock.callArgs, &mm_params)
	mmWithf.WithfMock.mutex.Unlock()

	for _, e := range mmWithf.WithfMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.l1
		}
	}

	if mmWithf.WithfMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmWithf.WithfMock.defaultExpectation.Counter, 1)
		mm_want := mmWithf.WithfMock.defaultExpectation.params
		mm_want_ptrs := mmWithf.WithfMock.defaultExpectation.paramPtrs

		mm_got := LoggerAliasMockWithfParams{key, value}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.key != nil && !minimock.Equal(*mm_want_ptrs.key, mm_got.key) {
				mmWithf.t.Errorf("LoggerAliasMock.Withf got unexpected parameter key, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmWithf.WithfMock.defaultExpectation.expectationOrigins.originKey, *mm_want_ptrs.key, mm_got.key, minimock.Diff(*mm_want_ptrs.key, mm_got.key))
			}

			if mm_want_ptrs.value != nil && !minimock.Equal(*mm_want_ptrs.value, mm_got.value) {
				mmWithf.t.Errorf("LoggerAliasMock.Withf got unexpected parameter value, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmWithf.WithfMock.defaultExpectation.expectationOrigins.originValue, *mm_want_ptrs.value, mm_got.value, minimock.Diff(*mm_want_ptrs.value, mm_got.value))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmWithf.t.Errorf("LoggerAliasMock.Withf got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmWithf.WithfMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmWithf.WithfMock.defaultExpectation.results
		if mm_results == nil {
			mmWithf.t.Fatal("No results are set for the LoggerAliasMock.Withf")
		}
		return (*mm_results).l1
	}
	if mmWithf.funcWithf != nil {
		return mmWithf.funcWithf(key, value)
	}
	mmWithf.t.Fatalf("Unexpected call to LoggerAliasMock.Withf. %v %v", key, value)
	return
}

