// Calls returns a list of arguments used in each call to LoggerAliasMock.Withf.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmWithf *mLoggerAliasMockWithf) Calls() []*LoggerAliasMockWithfParams {
	mmWithf.mutex.RLock()

	argCopy := make([]*LoggerAliasMockWithfParams, len(mmWithf.callArgs))
	copy(argCopy, mmWithf.callArgs)

	mmWithf.mutex.RUnlock()

	return argCopy
}

// MinimockWithfDone returns true if the count of the Withf invocations corresponds
// the number of defined expectations
func (m *LoggerAliasMock) MinimockWithfDone() bool {
	if m.WithfMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.WithfMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.WithfMock.invocationsDone()
}

// MinimockWithfInspect logs each unmet expectation
func (m *LoggerAliasMock) MinimockWithfInspect() {
	for _, e := range m.WithfMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to LoggerAliasMock.Withf at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterWithfCounter := mm_atomic.LoadUint64(&m.afterWithfCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.WithfMock.defaultExpectation != nil && afterWithfCounter < 1 {
		if m.WithfMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to LoggerAliasMock.Withf at\n%s", m.WithfMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to LoggerAliasMock.Withf at\n%s with params: %#v", m.WithfMock.defaultExpectation.expectationOrigins.origin, *m.WithfMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcWithf != nil && afterWithfCounter < 1 {
		m.t.Errorf("Expected call to LoggerAliasMock.Withf at\n%s", m.funcWithfOrigin)
	}

	if !m.WithfMock.invocationsDone() && afterWithfCounter > 0 {
		m.t.Errorf("Expected %d calls to LoggerAliasMock.Withf at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.WithfMock.expectedInvocations), m.WithfMock.expectedInvocationsOrigin, afterWithfCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *LoggerAliasMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockDebugfInspect()

			m.MinimockErrorfInspect()

			m.MinimockFatalfInspect()

			m.MinimockInfofInspect()

			m.MinimockSyncInspect()

			m.MinimockWarnfInspect()

			m.MinimockWithfInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *LoggerAliasMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *LoggerAliasMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockDebugfDone() &&
		m.MinimockErrorfDone() &&
		m.MinimockFatalfDone() &&
		m.MinimockInfofDone() &&
		m.MinimockSyncDone() &&
		m.MinimockWarnfDone() &&
		m.MinimockWithfDone()
}
